function App() {
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    const t = setTimeout(() => setLoaded(true), 800);
    return () => clearTimeout(t);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>Fallback metrics matter</h3>
      <p style={{ lineHeight: loaded ? '2' : '1.2', transition: 'none' }}>
        {loaded ? 'Real font loaded' : 'Fallback showing…'} — a mismatched fallback jumps the layout (CLS). next/font matches metrics so this line would NOT move.
      </p>
    </div>
  );
}

